#include <cstdio>
#include <ranges>
#include <vector>

int calls = 0;

int main() {
  std::vector<int> v{1, 2, 3, 4};
  auto r = v | std::views::transform([](int x) { ++calls; return x; })
             | std::views::filter([](int x) { return x % 2 == 0; });
  for (int x : r) (void)x;
  std::printf("%d ", calls);
  calls = 0;
  for (int x : r) (void)x;
  std::printf("%d\n", calls);
}

#include <ranges>
#include <vector>

void show(const auto& r) {
  for (int x : r) (void)x;
}

int main() {
  std::vector<int> v{1, 2, 3, 4};
  show(v | std::views::filter([](int x) { return x % 2 == 0; }));
}

